#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
# Copyright 2026 Tom F. <tomf@tomtomtech.net> (https://github.com/tomtom215)
#
# Asserts that the numbers quoted in `book/src/reference/benchmarks.md` prose
# still agree with the measurement tables on the same page.
#
# Why this exists. The page is generated by
# `benches/scripts/generate_book_page.sh`: the tables are emitted from
# criterion's estimates.json, the prose was typed by hand into a quoted
# heredoc. So the tables regenerated on every bench run and the prose did not.
# Between v0.5.0 and v0.8.0 the page simultaneously stated:
#
#   prose : "the ~1.4ms HTTP round-trip dominates"
#   table : transport_payload_scaling/jsonrpc_send/64 = 189.9 µs
#
#   prose : "connection reuse saves ~140µs (9%)"
#   table : 312.5 µs new client vs 189.0 µs reused  ->  123.5 µs, 39.5%
#
# The second understated connection reuse by more than 4x, in a document whose
# whole job is to be quotable. This is the same failure the file-length ratchet
# was built to cure, and its header already names the rule: a number nothing
# recomputes is a number that decays.
#
# The generator now interpolates both paragraphs from the same estimates the
# tables come from, so a fresh `cargo bench` + regenerate keeps them true. This
# script is the ratchet for the gap that fix cannot close: the page is a
# committed artifact, editable by hand, and regenerated only when someone runs
# the benchmarks. It re-derives the quoted values from the committed tables and
# fails if the prose has drifted from them.
#
# Deliberately narrow. It checks named claims, not every number on the page. A
# generic "find every number in the prose" heuristic would flag version strings,
# section headings and payload sizes, and a gate that cries wolf gets routed
# around. New quoted measurements should be added here explicitly.
#
# Three claims are covered: transport payload insensitivity, connection reuse
# impact, and the burst client-sharing A/B. The third is checked against its own
# table rather than the generated measurement tables, because it is quoted per
# agent while those tables carry whole-burst medians.
#
# Two structural rules make the difference between this catching drift and
# merely appearing to, and both were established by mutation rather than
# reasoning — each was found by a mutation that the gate initially passed:
#
#   1. Sentences are checked against prose with table rows stripped. Otherwise
#      the table row that supplied a value satisfies the search for it, and a
#      sentence can be edited back to a stale figure undetected.
#   2. Each claim is checked inside its own `###` section. Otherwise one
#      section vouches for another's numbers — concretely, the burst A/B
#      section quotes the connection-reuse saving in order to contrast with it,
#      which masked a reintroduction of the original "~140µs (9%)" bug.
#
# Usage:
#   ./scripts/check_benchmark_prose.sh
#
# Exit codes:
#   0  prose agrees with the tables
#   1  prose has drifted, or a table row the prose depends on is missing

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PAGE="$REPO_ROOT/book/src/reference/benchmarks.md"

if [ ! -f "$PAGE" ]; then
    echo "check_benchmark_prose: $PAGE not found" >&2
    exit 1
fi

python3 - "$PAGE" <<'PY'
import re
import sys

page = sys.argv[1]
text = open(page, encoding="utf-8").read()

# The prose, with every table row removed.
#
# This distinction is the whole point of the script and is easy to lose: the
# values it looks for appear twice on the page, once in a table and once in a
# sentence. Searching the raw text for "59.2 µs (18.1%)" is satisfied by the
# table row that supplied it, so a sentence could be edited back to a stale
# figure and still pass — the exact drift this gate exists to catch. Tables are
# read via `table_ns`/`AB_ROW` against the full text; sentences are checked
# against this.
prose = "\n".join(
    line for line in text.splitlines() if not line.lstrip().startswith("|")
)

# Prose split by `###` heading, so each claim is checked inside its own section.
#
# Whole-page substring checks are not enough, and the reason is a live hazard
# rather than a hypothetical: the burst A/B section quotes the connection-reuse
# saving too, in order to contrast with it. That second mention would satisfy a
# page-wide search for "123.5 µs (39.5%)" even if the connection-reuse
# paragraph itself had drifted back to the "~140µs (9%)" this gate was written
# to catch. One section vouching for another's numbers is exactly the failure
# mode here, so each claim is confined to the section that owns it.
SECTIONS = {}
_current = None
for line in prose.splitlines():
    if line.startswith("### "):
        _current = line[4:].strip()
        SECTIONS[_current] = []
    elif _current is not None:
        SECTIONS[_current].append(line)
SECTIONS = {k: "\n".join(v) for k, v in SECTIONS.items()}

def section(title):
    """Body of a named `###` section, or None (recorded as a failure)."""
    if title not in SECTIONS:
        print(f"  MISSING SECTION  {title!r}")
        print("    a claim this script checks lives in a section that is gone")
        return None
    return SECTIONS[title]

UNITS = {"ns": 1.0, "µs": 1_000.0, "us": 1_000.0, "ms": 1_000_000.0}

def table_ns(row):
    """Median for a table row, in nanoseconds.

    Rows look like: | `transport_payload_scaling/jsonrpc_send/64` | 189.9 µs |
    """
    pattern = r"\|\s*`" + re.escape(row) + r"`\s*\|\s*([0-9.]+)\s*(ns|µs|us|ms)\s*\|"
    m = re.search(pattern, text)
    if not m:
        print(f"  MISSING TABLE ROW  {row}")
        print("    the prose quotes this measurement but no table row supplies it")
        return None
    return float(m.group(1)) * UNITS[m.group(2)]

def fmt(ns):
    """Render like generate_book_page.sh's extract_median."""
    if ns >= 1_000_000:
        return f"{ns / 1_000_000:.2f} ms"
    if ns >= 1_000:
        return f"{ns / 1_000:.1f} µs"
    return f"{ns:.0f} ns"

failures = []
missing = False

# ── Claim 1: transport payload insensitivity ─────────────────────────────
small = table_ns("transport_payload_scaling/jsonrpc_send/64")
large = table_ns("transport_payload_scaling/jsonrpc_send/16384")
sec1 = section("Transport payload insensitivity")
if small is None or large is None or sec1 is None:
    missing = True
else:
    pct = f"{((large - small) / small) * 100:.1f}%"
    baseline = fmt(small)
    for want, label in ((pct, "64B->16KB latency increase"),
                        (baseline, "HTTP round-trip baseline")):
        if want not in sec1:
            failures.append(
                f"prose does not contain {want!r} ({label}); "
                f"recomputed from the tables on this page"
            )

# ── Claim 2: connection reuse impact ─────────────────────────────────────
new_client = table_ns("realistic_connection/new_client_per_request")
reused = table_ns("realistic_connection/reused_client")
sec2 = section("Connection reuse impact")
if new_client is None or reused is None or sec2 is None:
    missing = True
else:
    saved = new_client - reused
    saving = (
        f"{saved / 1_000:.1f} µs" if saved >= 1_000 else f"{saved:.0f} ns"
    )
    pct = f"{(saved / new_client) * 100:.1f}%"
    checks = (
        (f"{saving} ({pct})", "connection-reuse saving"),
        (fmt(new_client), "new-client-per-request cost"),
        (fmt(reused), "reused-client cost"),
    )
    for want, label in checks:
        if want not in sec2:
            failures.append(
                f"prose does not contain {want!r} ({label}); "
                f"recomputed from the tables on this page"
            )

# ── Claim 3: burst client-sharing A/B ────────────────────────────────────
#
# This one is checked against its own table rather than the generated
# measurement tables, because the A/B is quoted per agent (µs/agent) while the
# tables carry whole-burst medians. Two distinct ways to drift are covered:
# the row arithmetic (saved and % must follow from the two costs beside them),
# and the summary sentence, which must quote the n=100 row rather than a
# remembered figure.
AB_ROW = re.compile(
    r"^\|\s*(\d+)\s*\|\s*([0-9.]+)\s*µs\s*\|\s*([0-9.]+)\s*µs\s*\|"
    r"\s*([0-9.]+)\s*µs\s*\(([0-9.]+)%\)\s*\|$",
    re.M,
)
ab_rows = AB_ROW.findall(text)
sec3 = section("What sharing a client is actually worth under concurrency")
if not ab_rows or sec3 is None:
    print("  MISSING TABLE  burst client-sharing A/B")
    print("    the prose quotes a shared-client saving but no A/B table supplies it")
    missing = True
else:
    # Tolerances admit display rounding, and nothing more. The generator
    # computes `saved` from full-precision nanoseconds, while this script can
    # only re-derive it from the µs the table displays: at n=100 the generator
    # emits 59.2 (326.74 - 267.57) where the rounded cells give 59.1. Each
    # input carries up to ±0.05 µs of rounding, so their difference carries up
    # to ±0.1; 0.15 clears that with margin while still catching a transposed
    # digit. The percentage inherits that ±0.15 over a ~330 µs base, i.e. under
    # 0.05 points, so 0.1 is the matching bound.
    SAVED_TOL_US = 0.15
    PCT_TOL_POINTS = 0.1

    # The burst sizes `bench_agent_burst_client_sharing` measures. Pinned
    # because the rest of this claim only checks rows that are present: drop
    # the n=10 row and every remaining row still reconciles, so the table would
    # narrow silently and the section would read as if 10 had never been run.
    # A coverage table that can quietly shrink is the same defect as prose that
    # can quietly decay.
    EXPECTED_BURSTS = {10, 50, 100}
    found_bursts = {int(r[0]) for r in ab_rows}
    if found_bursts != EXPECTED_BURSTS:
        for n in sorted(EXPECTED_BURSTS - found_bursts):
            failures.append(
                f"burst A/B table has no row for n={n}, but the benchmark "
                f"measures it — the table narrowed without the prose saying so"
            )
        for n in sorted(found_bursts - EXPECTED_BURSTS):
            failures.append(
                f"burst A/B table has a row for n={n}, which the benchmark "
                f"does not measure; update EXPECTED_BURSTS if it now does"
            )

    checked_ab = 0
    for n, per_agent, shared, saved, pct in ab_rows:
        want_saved = float(per_agent) - float(shared)
        want_pct = (want_saved / float(per_agent)) * 100
        if abs(want_saved - float(saved)) > SAVED_TOL_US:
            failures.append(
                f"burst A/B row n={n}: saved reads {saved} µs, but "
                f"{per_agent} - {shared} = {want_saved:.1f} µs"
            )
        if abs(want_pct - float(pct)) > PCT_TOL_POINTS:
            failures.append(
                f"burst A/B row n={n}: saving reads {pct}%, but "
                f"{want_saved:.1f}/{per_agent} = {want_pct:.1f}%"
            )
        checked_ab += 2

    # The summary sentence must quote the largest burst measured, not a
    # figure remembered from the sequential benchmark above it.
    largest = max(ab_rows, key=lambda r: int(r[0]))
    want = f"{largest[3]} µs ({largest[4]}%)"
    if want not in sec3:
        failures.append(
            f"prose does not contain {want!r} (shared-client saving at the "
            f"largest burst, n={largest[0]}); recomputed from the A/B table"
        )
    checked_ab += 1

if missing or failures:
    print("check_benchmark_prose: benchmarks.md prose disagrees with its own tables")
    for f in failures:
        print(f"  DRIFT  {f}")
    print()
    print("  The prose on this page quotes measurements. Regenerate it with")
    print("    cargo bench -p a2a-benchmarks && ./benches/scripts/generate_book_page.sh")
    print("  rather than editing the numbers by hand.")
    sys.exit(1)

print(
    f"check_benchmark_prose: {5 + checked_ab} quoted value(s) agree with "
    "the tables on the page"
)
PY
